/bin/bash -lc "python - <<'PY'
from catalog.saturday_weekend import is_weekend

assert [is_weekend(day) for day in range(7)] == [False] * 5 + [True, True]
for value in (-1, 7, True, False, 5.0, '5', None):
    try:
        is_weekend(value)
    except ValueError as error:
        assert str(error) == 'weekday must be an integer from 0 to 6'
    else:
        raise AssertionError(f'Accepted invalid weekday: {value"'!r}'"')
print('All weekdays and integer-range validation checks passed.')
PY"

